            print("Successfully connected to the P2P network!")
        except Exception as e:
            self.connected = False
            print(f"Failed to connect to the P2P network: {e}")

    def retrieve_peer_list(self):
        """Simulate retrieving peer list."""
        if not self.connected:
            print("Cannot retrieve peers: Not connected to the network.")
            return
        try:
            print("Retrieving peer list...")
            time.sleep(random.uniform(0.5, 1.5))  # Simulate delay
            self.peers = [f"Peer_{i}" for i in range(1, random.randint(3, 7))]
            print(f"Peer list retrieved: {self.peers}")
        except Exception as e:
            print(f"Failed to retrieve peer list: {e}")

